/** Short human-readable description of a failed REST call, for the error message. */
export function describeError(error: unknown): string {
  if (error instanceof HttpErrorResponse) {
    return error.status ? `server responded ${error.status}` : 'the server could not be reached';
  }
  return error instanceof Error ? error.message : String(error);
