import { Component, OnInit, computed, inject, signal } from '@angular/core';
import { forkJoin, of, switchMap } from 'rxjs';

import { ApiService } from '../api.service';
import { describeError } from '../errors';
import { ManufacturerDto } from '../models';
import { MessageService } from '../messages/message.service';
import { RowKeys } from '../row-keys';
import { ManufacturerEditorComponent } from './manufacturer-editor.component';

/** The editor popup: `source` is the list entry being edited (null when creating). */
interface EditSession {
  source: ManufacturerDto | null;
  draft: ManufacturerDto;
}

@Component({
  selector: 'app-manufacturer-page',
  standalone: true,
  imports: [ManufacturerEditorComponent],
  template: `
    <div class="page-title">
      <h2>Manufacturers</h2>
      <button id="gwt-debug-create-manufacturer" type="button" class="add-action" (click)="create()">
        New manufacturer
      </button>
    </div>

    <div class="table-wrapper">
      <table id="gwt-debug-manufacturers" class="data-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Edit</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          @for (row of rows(); track row.key) {
            <tr>
              <td>{{ row.manufacturer.id }}</td>
              <td>{{ row.manufacturer.name }}</td>
              <td><button type="button" (click)="edit(row.manufacturer)">Edit</button></td>
              <td><button type="button" (click)="remove(row.manufacturer)">Delete</button></td>
            </tr>
          }
        </tbody>
      </table>
    </div>

    @if (session(); as current) {
      <app-manufacturer-editor
        [manufacturer]="current.draft"
        (saved)="onSaved(current.source, $event)"
        (closed)="session.set(null)"
      />
    }
  `,
  styles: [
    `
      .table-wrapper {
        margin-top: 20px;
      }
    `,
  ],
})
export class ManufacturerPageComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);
  private readonly keys = new RowKeys();

  readonly manufacturers = signal<ManufacturerDto[]>([]);
  readonly session = signal<EditSession | null>(null);

  /**
   * Bumped whenever the editor opens. The row keys include it, so the table rows are
   * rebuilt behind the popup (as the GWT CellTable was) and the clicked Edit button is replaced.
   */
  private readonly generation = signal(0);
  private generationCounter = 0;

  readonly rows = computed(() => {
    const generation = this.generation();
    return this.manufacturers().map((manufacturer) => ({
      key: `${generation}:${this.keys.keyOf(manufacturer)}`,
      manufacturer,
    }));
  });

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (list) => this.manufacturers.set(list),
      error: (err) => this.messages.error(`Could not load manufacturers: ${describeError(err)}`),
    });
  }

  create(): void {
    this.openEditor(null, { name: '' });
  }

  edit(manufacturer: ManufacturerDto): void {
    this.openEditor(manufacturer, { ...manufacturer });
  }

  /** Edits replace their list entry in place; creates are appended, as in GWT. */
  onSaved(source: ManufacturerDto | null, saved: ManufacturerDto): void {
    if (source) {
      this.keys.transfer(source, saved);
      this.manufacturers.update((list) => list.map((m) => (m === source ? saved : m)));
    } else {
      this.manufacturers.update((list) => [...list, saved]);
    }
    this.session.set(null);
  }

  remove(manufacturer: ManufacturerDto): void {
    if (!window.confirm(`Are you sure you want to delete ${manufacturer.name}?`)) {
      return;
    }
    // The API does not cascade manufacturer deletes: the cars would keep a missing manufacturer,
    // and the averages report would then fail. So the cars go first (the API drops their ratings too).
    this.api
      .getCars()
      .pipe(
        switchMap((cars) => {
          const own = cars.filter((car) => car.manufacturer?.id === manufacturer.id);
          return own.length > 0 ? forkJoin(own.map((car) => this.api.deleteCar(car.id))) : of(undefined);
        }),
        switchMap(() => this.api.deleteManufacturer(manufacturer.id!)),
      )
      .subscribe({
        next: () => this.manufacturers.update((list) => list.filter((m) => m !== manufacturer)),
        error: (err) => this.messages.error(`Could not delete ${manufacturer.name}: ${describeError(err)}`),
      });
  }

  private openEditor(source: ManufacturerDto | null, draft: ManufacturerDto): void {
    this.generation.set(++this.generationCounter);
    this.session.set({ source, draft });
  }
}
