        inset: 0;
        background: rgba(0, 0, 0, 0.3);
        z-index: 1000;
      }
      .popup {
        position: fixed;
        top: 30%;
        left: 50%;
        transform: translateX(-50%);
        background: #fff;
        border: 1px solid #45a0ec;
        border-radius: 4px;
