      .field label {
        display: inline-block;
        width: 100px;
      }
      .actions {
        display: flex;
        gap: 8px;
      }
    `,
  ],
})
export class RatingEditorComponent implements OnChanges {
  @Input() cars: CarDto[] = [];
  @Output() saved = new EventEmitter<RatingDto>();
  @Output() closed = new EventEmitter<void>();

  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  protected readonly carLabel = carLabel;
  selectedCar: CarDto | null = null;
  rating: number | null = null;
  readonly saving = signal(false);

  ngOnChanges(): void {
    // Default to the first car, as the GWT picker did, once the car list is known.
    if (this.selectedCar === null && this.cars.length > 0) {
