    this.api.saveRating(dto).subscribe({
      next: (savedRating) => {
        this.saving.set(false);
        this.messages.success('Rating saved.');
        this.saved.emit(savedRating);
      },
      error: (err) => {
        this.saving.set(false);
        this.messages.error(`Could not save rating: ${describeError(err)}`);
      },
    });
  }
