/**
 * Stable, unique @for track keys for objects. Keys by object identity rather than server id,
 * so a list stays correct even if the server hands out an id that is already on screen.
 */
export class RowKeys {
  private readonly ids = new WeakMap<object, number>();
  private next = 0;

  keyOf(item: object): number {
    let key = this.ids.get(item);
    if (key === undefined) {
      key = ++this.next;
      this.ids.set(item, key);
    }
    return key;
  }

  /** Re-uses the key of `previous` for `replacement`, so an updated row keeps its DOM. */
  transfer(previous: object, replacement: object): void {
    this.ids.set(replacement, this.keyOf(previous));
  }
}
