import { HashLocationStrategy, PlatformLocation } from '@angular/common';

/**
 * Hash location strategy whose URLs look like the GWT history tokens:
 * `/ng/#manufacturer` instead of Angular's default `/ng/#/manufacturer`.
 * The router still accepts both forms when reading the hash.
 */
export class TokenHashLocationStrategy extends HashLocationStrategy {
  constructor(platformLocation: PlatformLocation) {
    super(platformLocation, undefined);
  }

  override prepareExternalUrl(internal: string): string {
    return '#' + internal.replace(/^\/+/, '');
  }
}
